pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;

    function setUp() public {
        c = new demo();
    }

    function testFuzz_property(address from, address caddress, uint256 v) public {
        address[] memory empty = new address[](0);

        bool ok;
        bool returnedValue;
        try c.transfer(from, caddress, empty, v) returns (bool r) {
            ok = true;
            returnedValue = r;
        } catch {
            ok = false;
        }

        // General rule: an empty recipient array is inadmissible, so the call must revert
        // and must NOT report success. The reference obeys this for every input; the mutant
        // removes the require and returns true, violating it for every empty-array input.
        assertTrue(!(ok && returnedValue));
    }
}
